Output:
js
function debounce(fn, wait = 200) {
  let t;
  return function debounced(...args) {
    const ctx = this;
    clearTimeout(t);
    t = setTimeout(() => fn.apply(ctx, args), wait);
  };
}

// usage
window.addEventListener('resize', debounce(() => {
  console.log('resized');
}, 250));
nnDebouncing delays execution until calls stop for wait ms.

