python
from typing import Any, Dict

TYPE_MAP = {
    'str': str,
    'int': int,
    'bool': bool,
    'list': list,
    'dict': dict,
}

def validate(obj: Dict[str, Any], schema: Dict[str, Any]) -> list[str]:
    errors = []
    required = schema.get('required', [])
    props = schema.get('properties', {})

    for key in required:
        if key not in obj:
            errors.append(f"missing required: {key}")

    for key, spec in props.items():
        if key not in obj:
            continue
        t = spec.get('type')
        if t and t in TYPE_MAP and not isinstance(obj[key], TYPE_MAP[t]):
            errors.append(f"{key} expected {t}, got {type(obj[key]).__name__}")

    return errors

sample = {"name": "A", "age": 10}
schema = {
  "required": ["name"],
  "properties": {"name": {"type": "str"}, "age": {"type": "int"}}
}
print(validate(sample, schema))

CORS controls whether a browser is allowed to read responses from another origin.

Express example:
js
import cors from 'cors';

app.use(cors({
  origin: 'https://app.example.com',
  methods: ['GET','POST'],
  credentials: true,
}));


Don’t use origin: '*' with credentials.

ts
function isString(x: unknown): x is string {
  return typeof x === 'string';
}

function len(x: unknown): number | null {
  if (!isString(x)) return null;
  return x.length;
}

- Macrotasks: setTimeout, I/O, UI events.
- Microtasks: Promise.then, queueMicrotask, MutationObserver.

Microtasks run after the current call stack and before the next macrotask.

Example:
js
console.log('A');
setTimeout(() => console.log('B'), 0);
Promise.resolve().then(() => console.log('C'));
console.log('D');

Order: A, D, C, B.

js
const controller = new AbortController();

async function load() {
  try {
    const res = await fetch('/api/data', { signal: controller.signal });
    return await res.json();
  } catch (e) {
    if (e.name === 'AbortError') return null;
    throw e;
  }
}

// later
controller.abort();

When you access obj.x, JS looks for x on obj. If not found, it looks on obj.__proto__ (the prototype), and continues up the chain until null.

Example:
js
const base = { greet() { return 'hi'; } };
const child = Object.create(base);
child.name = 'A';
console.log(child.greet()); // found via prototype

The prototype chain enables shared methods without copying them to every object.

A closure is when a function “remembers” variables from its surrounding scope even after that scope has returned.

Example:
js
function makeCounter() {
  let n = 0;
  return () => ++n;
}
const c = makeCounter();
console.log(c()); // 1
console.log(c()); // 2

Here the inner function closes over n.

sql
CREATE INDEX CONCURRENTLY idx_orders_user_id ON orders(user_id);

EXPLAIN ANALYZE
SELECT * FROM orders WHERE user_id = 42;


Look for an Index Scan (or Bitmap Index Scan) rather than a Seq Scan. Measure before/after.

A transaction groups multiple statements so they either all succeed or all fail.

sql
BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;
-- if something fails: ROLLBACK;

Use transactions for invariants like “money is conserved”.

ts
type Circle = { kind: 'circle'; r: number };
type Rect = { kind: 'rect'; w: number; h: number };
type Shape = Circle | Rect;

function area(s: Shape): number {
  switch (s.kind) {
    case 'circle': return Math.PI * s.r * s.r;
    case 'rect': return s.w * s.h;
  }
}
